    private static void reject(Work work,String text)throws Exception{boolean failed=false;try{work.run();}catch(IOException e){failed=String.valueOf(e.getMessage()).contains(text);}check(failed,"Reject "+text);}
    private static byte[] hex(String value){byte[] b=new byte[value.length()/2];for(int n=0;n<b.length;n++)b[n]=(byte)Integer.parseInt(value.substring(n*2,n*2+2),16);return b;}
    private static String hash(byte[] bytes)throws Exception{StringBuilder text=new StringBuilder();for(byte b:MessageDigest.getInstance("SHA-256").digest(bytes))text.append(String.format(Locale.ROOT,"%02x",b&255));return text.toString();}
    private static int[] ints(String value){if(value.isEmpty())return new int[0];String[] parts=value.split(",");int[] out=new int[parts.length];for(int i=0;i<out.length;i++)out[i]=Integer.parseInt(parts[i]);return out;}
