    private static Pc1TextLayout fresh()throws Exception{Pc1TextLayout l=new Pc1TextLayout(config());l.position(20,40,28);return l;}
    private static Pc1TextLayout.Source source(String id,String bytes,int size)throws Exception{byte[] raw=hex(bytes),backing=new byte[size];System.arraycopy(raw,0,backing,0,raw.length);return new Pc1TextLayout.Source(id,backing);}
    private static int[] state(Pc1TextLayout.Snapshot s){return new int[]{s.x,s.y,s.fontSize,s.rubyPhase,s.rubyCount,s.baseCount,s.rubyCursor,s.rubyOrigin,s.rubyGap,s.dictionaryCount,s.cursor};}
    private static byte[] save(Pc1TextLayout.Snapshot snapshot)throws Exception{ByteArrayOutputStream b=new ByteArrayOutputStream();snapshot.save(new DataOutputStream(b));return b.toByteArray();}
    private static Pc1TextLayout.Snapshot load(byte[] bytes)throws Exception{return Pc1TextLayout.Snapshot.load(new DataInputStream(new ByteArrayInputStream(bytes)));}
    // Earlier machine vectors deliberately omitted absolute source pointers.
    // Normalize only this comparison, never the canonical/frozen native row.
    private static byte[] records(Pc1TextLayout.Snapshot s)throws Exception{ByteArrayOutputStream b=new ByteArrayOutputStream();for(int n=0;n<10;n++){byte[] row=s.nativeDictionaryRecord(n);Arrays.fill(row,556,560,(byte)0);b.write(row);}return b.toByteArray();}
