        Pc1TextLayout live4c=fresh();live4c.step(source("body","816f81418142a3af81438144a3fd8170",1024),0,0,true,100);live4c.step(source("body","816f81418142a3af81438144a3fd8170",1024),8,0,true,100);Pc1TextLayout.Snapshot phaseBefore=live4c.freeze();check(phaseBefore.rubyPhase==1&&phaseBefore.rubyCursor==2,"4C reset fixture pauses active ruby after one glyph");live4c.resetRubyPhase();Pc1TextLayout.Snapshot phaseAfter=live4c.freeze();check(phaseAfter.rubyPhase==0&&phaseAfter.rubyCount==phaseBefore.rubyCount&&phaseAfter.baseCount==phaseBefore.baseCount&&phaseAfter.rubyCursor==phaseBefore.rubyCursor&&phaseAfter.rubyOrigin==phaseBefore.rubyOrigin&&phaseAfter.rubyGap==phaseBefore.rubyGap&&Arrays.equals(phaseAfter.rubyBacking(),phaseBefore.rubyBacking()),"Live4C resets only ruby phase, preserving all other ruby owners");check(Arrays.equals(phaseAfter.encodedWordsBacking(),phaseBefore.encodedWordsBacking())&&phaseAfter.cursor==phaseBefore.cursor&&phaseAfter.x==phaseBefore.x&&phaseAfter.y==phaseBefore.y&&phaseAfter.glyphs().size()==phaseBefore.glyphs().size(),"Live4C reset preserves cursor, dictionary and existing glyph journal");
        Pc1TextLayout sameDelimiter=new Pc1TextLayout(new Pc1TextLayout.Config(20,36,200,16,6,0x1234,0xfda3,0xfda3));sameDelimiter.position(20,40,28);sameDelimiter.step(source("same","816f8141a3fd8142a3fd8170",1024),0,0,true,100);check(sameDelimiter.freeze().rubyCount==1&&sameDelimiter.freeze().baseCount==1,"Ruby split test precedes stop when configured delimiters coincide");
